<?php if ( ! defined( 'ABSPATH' ) ) { exit; } if($o['cart_drawer']!=='1') return; ?>
<aside class="seh-cart-drawer" hidden style="--seh-cart-width:<?php echo absint($o['cart_width']); ?>px;background:<?php echo esc_attr($o['cart_bg']); ?>"><button class="seh-close" aria-label="<?php esc_attr_e('Close cart','simple-ecommerce-header'); ?>" data-seh-close>×</button><h2><?php esc_html_e('Shopping Cart','simple-ecommerce-header'); ?> (<span class="seh-cart-count"><?php echo esc_html($woo->count()); ?></span>)</h2><div class="seh-cart-items"><?php if($woo->active() && $woo->cart_items()): foreach($woo->cart_items() as $key=>$item): $product=$item['data']; ?><div class="seh-cart-item" data-cart-key="<?php echo esc_attr($key); ?>"><?php echo wp_kses_post($product->get_image('thumbnail')); ?><div><strong><?php echo esc_html($product->get_name()); ?></strong><span><?php echo wp_kses_post(wc_price($product->get_price())); ?></span><?php if($o['qty_controls']==='1'): ?><div><button data-seh-qty="down">−</button><input value="<?php echo esc_attr($item['quantity']); ?>" readonly><button data-seh-qty="up">+</button></div><?php endif; ?></div><?php if($o['remove_item']==='1'): ?><button aria-label="<?php esc_attr_e('Remove item','simple-ecommerce-header'); ?>" data-seh-remove>×</button><?php endif; ?></div><?php endforeach; else: ?><p class="seh-empty"><?php esc_html_e('Your cart is empty. Add products to see them here.','simple-ecommerce-header'); ?></p><?php endif; ?></div><?php if($o['show_subtotal']==='1'): ?><div class="seh-cart-subtotal"><span><?php esc_html_e('Subtotal','simple-ecommerce-header'); ?></span><strong><?php echo wp_kses_post($woo->subtotal()); ?></strong></div><?php endif; ?><p><?php echo esc_html($o['shipping_text']); ?></p><a class="seh-cart-btn" href="<?php echo esc_url($woo->cart_url()); ?>"><?php echo esc_html($o['cart_button_text']); ?></a><a class="seh-checkout-btn" href="<?php echo esc_url($woo->checkout_url()); ?>"><?php echo esc_html($o['checkout_button_text']); ?></a></aside>
